content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --border-color: #e5e7eb;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  padding: 20px;
}

.app-container {
  max-width: 600px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.calculator-card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: 32px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.title {
  font-size: 24px;
  font-weight: 700;
  text-align: center;
  color: var(--text-main);
  margin-bottom: 8px;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.label {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-main);
}

.input-field {
  width: 100%;
  padding: 12px 16px;
  font-size: 16px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input-field:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.15);
}

.calculate-btn {
  background-color: var(--primary-color);
  color: #ffffff;
  font-size: 16px;
  font-weight: 600;
  padding: 14px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  margin-top: 8px;
}

.calculate-btn:hover {
  background-color: var(--primary-hover);
}

.calculate-btn:active {
  transform: scale(0.98);
}

.result-container {
  background-color: #f9fafb;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 20px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 10px;
}

.bmi-value {
  font-size: 36px;
  font-weight: 800;
  color: var(--primary-color);
}

.bmi-category {
  font-size: 18px;
  font-weight: 600;
  padding: 4px 12px;
  border-radius: 20px;
  display: inline-block;
  margin: 0 auto;
}

.history-section {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px 32px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.history-section h3 {
  font-size: 18px;
  font-weight: 700;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 8px;
}

.history-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: 250px;
  overflow-y: auto;
}

.history-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  background-color: #f9fafb;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-size: 14px;
}

.history-item-info {
  display: flex;
  gap: 16px;
  color: var(--text-muted);
}

.history-item-bmi {
  font-weight: 700;
  color: var(--text-main);
}

@media (max-width: 480px) {
  body {
    padding: 10px;
  }
  .calculator-card, .history-section {
    padding: 20px;
  }
}

import { useState } from 'react';

interface HistoryItem {
  id: string;
  date: string;
  height: number;
  weight: number;
  bmi: number;
  category: string;
}

export default function App() {
  const [height, setHeight] = useState<string>('');
  const [weight, setWeight] = useState<string>('');
  const [history, setHistory] = useState<HistoryItem[]>([]);

  const calcBmi = (h: number, w: number) => {
    if (h <= 0 || w <= 0) return null;
    const heightM = h / 100;
    return w / (heightM * heightM);
  };

  const getBmiCategory = (bmi: number) => {
    if (bmi < 18.5) return { text: '低体重（痩せ）', color: '#3b82f6' };
    if (bmi < 25) return { text: '普通体重', color: '#10b981' };
    if (bmi < 30) return { text: '肥満（1度）', color: '#f59e0b' };
    if (bmi < 35) return { text: '肥満（2度）', color: '#f97316' };
    if (bmi < 40) return { text: '肥満（3度）', color: '#ef4444' };
    return { text: '肥満（4度）', color: '#b91c1c' };
  };

  const hNum = parseFloat(height);
  const wNum = parseFloat(weight);
  const currentBmi = (!isNaN(hNum) && !isNaN(wNum)) ? calcBmi(hNum, wNum) : null;
  const currentCategory = currentBmi !== null ? getBmiCategory(currentBmi) : null;

  const handleCalculate = (e: React.FormEvent) => {
    e.preventDefault();
    if (currentBmi === null || isNaN(hNum) || isNaN(wNum)) return;

    const newItem: HistoryItem = {
      id: Date.now().toString(),
      date: new Date().toLocaleString('ja-JP', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }),
      height: hNum,
      weight: wNum,
      bmi: parseFloat(currentBmi.toFixed(1)),
      category: currentCategory ? currentCategory.text : ''
    };

    setHistory([newItem, ...history]);
  };

  return (
    <div className="app-container">
      <div className="calculator-card">
        <h1 className="title">BMI 計算ツール</h1>
        <form onSubmit={handleCalculate} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <div className="input-group">
            <label className="label" htmlFor="height">身長 (cm)</label>
            <input
              id="height"
              className="input-field"
              type="number"
              step="0.1"
              placeholder="例: 170"
              value={height}
              onChange={(e) => setHeight(e.target.value)}
              required
            />
          </div>

          <div className="input-group">
            <label className="label" htmlFor="weight">体重 (kg)</label>
            <input
              id="weight"
              className="input-field"
              type="number"
              step="0.1"
              placeholder="例: 65"
              value={weight}
              onChange={(e) => setWeight(e.target.value)}
              required
            />
          </div>

          <button type="submit" className="calculate-btn">
            計算して履歴に保存
          </button>
        </form>

        {currentBmi !== null && currentCategory && (
          <div className="result-container">
            <div style={{ fontSize: '14px', color: 'var(--text-muted)' }}>あなたのBMI</div>
            <div className="bmi-value">{currentBmi.toFixed(1)}</div>
            <div>
              <span 
                className="bmi-category" 
                style={{ backgroundColor: `${currentCategory.color}20`, color: currentCategory.color }}
              >
                {currentCategory.text}
              </span>
            </div>
          </div>
        )}
      </div>

      {history.length > 0 && (
        <div className="history-section">
          <h3>計算履歴</h3>
          <div className="history-list">
            {history.map((item) => (
              <div key={item.id} className="history-item">
                <div className="history-item-info">
                  <span>{item.date}</span>
                  <span>身長: {item.height}cm / 体重: {item.weight}kg</span>
                </div>
                <div className="history-item-bmi">
                  BMI: {item.bmi} ({item.category})
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
